import nltk
from string import punctuation
import pandas as pd

def task_func(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")

    counts = {}

    for token in text.split():
        if token.startswith("$") and not all(ch in punctuation for ch in token):
            counts[token] = counts.get(token, 0) + 1

    return pd.DataFrame(
        [{"Word": word, "Frequency": freq} for word, freq in counts.items()],
        columns=["Word", "Frequency"]
    )
